// Model detector: the trained network in the detector slot.
// Streaming C++ port of bench/hush_bench/features.py (log-mel) and
// bench/hush_bench/detectors/model.py (network + decision rule). The bench
// checks that both make the same decisions. Weights are compiled in from
// src/model_weights.inc (generated by train/export_cpp.py).
#pragma once
#include <complex>
#include <vector>

#include "hush/detector.hpp"

namespace hush {

// Decision rule. Defaults are the values tuned on validation calls.
struct ModelParams {
  double on_th, off_th, lead_s, tail_s, min_hold_s, merge_s;
  int on_frames, off_frames;
  static ModelParams tuned();
};

class ModelDetector final : public Detector {
 public:
  explicit ModelDetector(ModelParams p = ModelParams::tuned()) : p_(p) {}
  const char* name() const override;
  void prepare(double sample_rate, size_t max_block) override;
  void process(const float* in, size_t n, uint64_t first_sample, MuteSink& sink) override;
  void reset() override;

  // Probability of the newest frame (for tools and UIs), -1 before the first.
  float last_probability() const { return last_p_; }

 private:
  struct Layer {
    int c_in = 0, c_out = 0, dil = 1, span = 0;
    const float* w = nullptr;  // [c_out][c_in][K]
    const float* b = nullptr;
    std::vector<float> hist;   // span input vectors, ring
    int pos = 0, filled = 0;
    std::vector<float> out;    // c_out
  };
  struct Band {
    size_t first = 0;
    std::vector<double> w;
  };

  void analyze_frame(MuteSink& sink);
  bool run_layers(const float* x);  // false until the network has a full history
  void decide(float p, MuteSink& sink);

  ModelParams p_;
  double sr_ = 16000;
  size_t win_ = 512, hop_ = 160, nfft_ = 512;
  std::vector<float> ring_;
  std::vector<double> window_, power_;
  double wsum2_ = 1;
  std::vector<std::complex<double>> fft_, tw_;
  std::vector<size_t> rev_;
  std::vector<Band> bands_;
  std::vector<float> feat_;
  std::vector<Layer> layers_;
  size_t ring_pos_ = 0;
  uint64_t seen_ = 0, frames_ = 0;
  float last_p_ = -1;

  // decision state (samples on the input timeline)
  bool active_ = false, have_last_ = false;
  int run_ = 0, below_ = 0;
  uint64_t cur_start_ = 0, last_end_ = 0;
  uint64_t lead_ = 0, tail_ = 0, hold_ = 0, merge_ = 0;
};

}  // namespace hush
